            Assert.assertEquals(selector.select(key.getBytes()), consumer3);
        } else {
            Assert.assertEquals(selector.select(key.getBytes()), consumer4);
        }
    }
    selector.removeConsumer(consumer3);
    for (int i = 0; i < 100; i++) {
        String key = UUID.randomUUID().toString();
        Assert.assertEquals(selector.select(key.getBytes()), consumer4);
    }
}

