@Test(timeOut = 20000)
public void testPulsarFunctionState() throws Exception {
    final String namespacePortion = "io";
    final String replNamespace = tenant + "/" + namespacePortion;
    final String sourceTopic = "persistent://" + replNamespace + "/input";
    final String sinkTopic = "persistent://" + replNamespace + "/output";
    final String propertyKey = "key";
    final String propertyValue = "value";
    final String functionName = "PulsarFunction-test";
    final String subscriptionName = "test-sub";
    admin.namespaces().createNamespace(replNamespace);
    Set<String> clusters = Sets.newHashSet(Lists.newArrayList("use"));
    admin.namespaces().setNamespaceReplicationClusters(replNamespace, clusters);
    // create a producer that creates a topic at broker
    Producer<String> producer = pulsarClient.newProducer(Schema.STRING).topic(sourceTopic).create();
    FunctionConfig functionConfig = createFunctionConfig(tenant, namespacePortion, functionName, sourceTopic, sinkTopic, subscriptionName);
    String jarFilePathUrl = Utils.FILE + ":" + getClass().getClassLoader().getResource("pulsar-functions-api-examples.jar").getFile();
    admin.functions().createFunctionWithUrl(functionConfig, jarFilePathUrl);
    retryStrategically((test) -> {
        try {
            return admin.topics().getStats(sourceTopic).subscriptions.size() == 1;
        } catch (PulsarAdminException e) {
            return false;
        }
    }, 5, 150);
    // validate pulsar sink consumer has started on the topic
    assertEquals(admin.topics().getStats(sourceTopic).subscriptions.size(), 1);
    int totalMsgs = 5;
    for (int i = 0; i < totalMsgs; i++) {
        String data = "foo";
        producer.newMessage().property(propertyKey, propertyValue).value(data).send();
    }
    retryStrategically((test) -> {
        try {
            SubscriptionStats subStats = admin.topics().getStats(sourceTopic).subscriptions.get(subscriptionName);
            return subStats.unackedMessages == 0;
        } catch (PulsarAdminException e) {
            return false;
        }
    }, 5, 150);
    retryStrategically((test) -> {
        try {
            FunctionStats functionStat = admin.functions().getFunctionStats(tenant, namespacePortion, functionName);
            return functionStat.getProcessedSuccessfullyTotal() == 5;
        } catch (PulsarAdminException e) {
            return false;
        }
    }, 5, 150);
    FunctionState state = admin.functions().getFunctionState(tenant, namespacePortion, functionName, "foo");
    Assert.assertEquals(state.getNumberValue().intValue(), 5);
    try {
        admin.functions().getFunctionState(tenant, namespacePortion, functionName, "bar");
        Assert.fail("Should have failed since key shouldn't exist");
    } catch (PulsarAdminException e) {
        Assert.assertEquals(e.getStatusCode(), Response.Status.NOT_FOUND.getStatusCode());
    }
    // validate pulsar-sink consumer has consumed all messages and delivered to Pulsar sink but unacked messages
    // due to publish failure
    assertNotEquals(admin.topics().getStats(sourceTopic).subscriptions.values().iterator().next().unackedMessages, totalMsgs);
    // delete functions
    admin.functions().deleteFunction(tenant, namespacePortion, functionName);
    retryStrategically((test) -> {
        try {
            return admin.topics().getStats(sourceTopic).subscriptions.size() == 0;
        } catch (PulsarAdminException e) {
            return false;
        }
    }, 5, 150);
    // make sure subscriptions are cleanup
    assertEquals(admin.topics().getStats(sourceTopic).subscriptions.size(), 0);
    // make sure all temp files are deleted
    File dir = new File(System.getProperty("java.io.tmpdir"));
    File[] foundFiles = dir.listFiles(new FilenameFilter() {

        public boolean accept(File dir, String name) {
            return name.startsWith("function");
        }
    });
    Assert.assertEquals(foundFiles.length, 0, "Temporary files left over: " + Arrays.asList(foundFiles));
}

