public void processUpdateTest() throws PulsarClientException {
    long version = 5;
    WorkerConfig workerConfig = new WorkerConfig();
    workerConfig.setWorkerId("worker-1");
    SchedulerManager schedulerManager = mock(SchedulerManager.class);
    FunctionMetaDataManager functionMetaDataManager = spy(new FunctionMetaDataManager(workerConfig, schedulerManager, mockPulsarClient()));
    // worker has no record of function
    Function.FunctionMetaData m1 = Function.FunctionMetaData.newBuilder().setFunctionDetails(Function.FunctionDetails.newBuilder().setName("func-1").setNamespace("namespace-1").setTenant("tenant-1")).setVersion(version).build();
    Request.ServiceRequest serviceRequest = Request.ServiceRequest.newBuilder().setServiceRequestType(Request.ServiceRequest.ServiceRequestType.UPDATE).setFunctionMetaData(m1).setWorkerId("worker-1").build();
    functionMetaDataManager.processUpdate(serviceRequest);
    verify(functionMetaDataManager, times(1)).setFunctionMetaData(any(Function.FunctionMetaData.class));
    verify(schedulerManager, times(1)).schedule();
    Assert.assertEquals(m1, functionMetaDataManager.functionMetaDataMap.get("tenant-1").get("namespace-1").get("func-1"));
    Assert.assertEquals(1, functionMetaDataManager.functionMetaDataMap.get("tenant-1").get("namespace-1").size());
    // worker has record of function
    // request is oudated
    schedulerManager = mock(SchedulerManager.class);
    functionMetaDataManager = spy(new FunctionMetaDataManager(workerConfig, schedulerManager, mockPulsarClient()));
    Function.FunctionMetaData m3 = Function.FunctionMetaData.newBuilder().setFunctionDetails(Function.FunctionDetails.newBuilder().setName("func-1").setNamespace("namespace-1").setTenant("tenant-1")).setVersion(version).build();
    functionMetaDataManager.setFunctionMetaData(m3);
    Function.FunctionMetaData outdated = Function.FunctionMetaData.newBuilder().setFunctionDetails(Function.FunctionDetails.newBuilder().setName("func-1").setNamespace("namespace-1").setTenant("tenant-1")).setVersion(version - 1).build();
    serviceRequest = Request.ServiceRequest.newBuilder().setServiceRequestType(Request.ServiceRequest.ServiceRequestType.UPDATE).setFunctionMetaData(outdated).setWorkerId("worker-1").build();
