private void testUpdateFunctionMissingArguments(String tenant, String namespace, String function, InputStream inputStream, Map<String, String> topicsToSerDeClassName, FormDataContentDisposition details, String outputTopic, String outputSerdeClassName, String className, Integer parallelism, String expectedError) {
    when(mockedManager.containsFunction(eq(tenant), eq(namespace), eq(function))).thenReturn(true);
    FunctionConfig functionConfig = new FunctionConfig();
    if (tenant != null) {
        functionConfig.setTenant(tenant);
    }
    if (namespace != null) {
        functionConfig.setNamespace(namespace);
    }
    if (function != null) {
        functionConfig.setName(function);
    }
    if (topicsToSerDeClassName != null) {
        functionConfig.setCustomSerdeInputs(topicsToSerDeClassName);
    }
    if (outputTopic != null) {
        functionConfig.setOutput(outputTopic);
    }
    if (outputSerdeClassName != null) {
        functionConfig.setOutputSerdeClassName(outputSerdeClassName);
    }
    if (className != null) {
        functionConfig.setClassName(className);
    }
    if (parallelism != null) {
        functionConfig.setParallelism(parallelism);
    }
    functionConfig.setRuntime(FunctionConfig.Runtime.JAVA);
    if (expectedError == null) {
        RequestResult rr = new RequestResult().setSuccess(true).setMessage("function registered");
        CompletableFuture<RequestResult> requestResult = CompletableFuture.completedFuture(rr);
        when(mockedManager.updateFunction(any(FunctionMetaData.class))).thenReturn(requestResult);
    }
    try {
        resource.updateFunction(tenant, namespace, function, inputStream, details, null, JsonFormat.printer().print(FunctionConfigUtils.convert(functionConfig, null)), null);
    } catch (InvalidProtocolBufferException e) {
        throw new RuntimeException(e);
    }
}

